args.sql:
SELECT f.userregistry, f.tierstep, m.membkind, m.spendusd
FROM fans f JOIN membershipandspending m ON f.userregistry = m.memberfanpivot
WHERE f.tierstep <= 3 AND m.spendusd < 100;

SELECT MIN(m.spendusd), MAX(m.spendusd), AVG(m.spendusd)
FROM fans f JOIN membershipandspending m ON f.userregistry = m.memberfanpivot
WHERE f.tierstep <= 3;

SELECT COUNT(DISTINCT f.userregistry) FROM fans f 
JOIN membershipandspending m ON f.userregistry = m.memberfanpivot
WHERE m.membkind IN ('Free', 'Basic');

SELECT m.membkind, COUNT(DISTINCT m.memberfanpivot) as fan_count
FROM membershipandspending m
GROUP BY m.membkind;

SELECT COUNT(DISTINCT f.userregistry) FROM fans f
JOIN membershipandspending m ON f.userregistry = m.memberfanpivot
WHERE m.membkind IN ('Free', 'Basic');
